-- ============================================================
-- spell_proc: Drain Life / Shadow Bolt / Haunt, 10% and 20%
-- ============================================================
-- SpellFamilyName 5 (Warlock).
--   SpellFamilyMask0 9       = 0x1 Shadow Bolt | 0x8 Drain Life
--   SpellFamilyMask1 262144  = 0x40000 Haunt
-- ProcFlags 327680 = 0x50000 = DONE_SPELL_MAGIC_DMG_CLASS_NEG | DONE_PERIODIC.
-- DONE_PERIODIC covers Drain Life, which does its damage as channel ticks;
-- Shadow Bolt and Haunt are direct hits and use the other half.
--
-- The 10/20% roll lives here, one row per rank, so the AuraScript is
-- unconditional.  SpellPhaseMask 2 is mandatory -- a zero phase mask makes
-- the proc silently never fire.

DELETE FROM `spell_proc` WHERE `SpellId` IN (200521, 200522);
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(200521, 0, 5, 9, 262144, 0, 327680, 1, 2, 0, 0, 0, 0, 10, 0, 0),
(200522, 0, 5, 9, 262144, 0, 327680, 1, 2, 0, 0, 0, 0, 20, 0, 0);


