-- ============================================================
-- talent_dbc: NEW talent 3004, gated on Fel Interdiction
-- ============================================================
-- Tier 8 Col 3 is empty in the stock Affliction tree and sits directly below
-- Fel Interdiction's new home at Tier 7 Col 3, so the prereq arrow is a clean
-- vertical.
--
-- PrereqTalent_1 = 1668, PrereqRank_1 = 0.  PrereqRank_1 is ZERO-INDEXED --
-- 0 means "rank 1 required".  Fel Interdiction is a 1-point talent, so
-- writing 1 here would demand a rank 2 that does not exist and leave
-- Malfeasance permanently unlearnable.  Same pattern as Pandemic (2245),
-- which gates on the 1-point Unstable Affliction with PrereqRank_1 = 0.
-- Flags = 0: passive, must not be added to the spellbook.
--
-- Record ordering is not a concern -- build_dbc.py re-sorts by
-- (TabID, TierID, ColumnIndex), which is what the client requires; appending
-- a new record in ID order would blank the entire tree.

DELETE FROM `talent_dbc` WHERE `ID` = 3004;
